import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { CalendarClock } from "lucide-react";

import { categories } from "@/data/categories";
import { getCalculatorContent } from "@/data/calculator-content";
import { calculatorRegistry } from "@/components/calculators/registry";
import { CalculatorCard } from "@/components/ui/CalculatorCard";
import { Breadcrumbs } from "@/components/seo/Breadcrumbs";
import { FaqSection } from "@/components/seo/FaqSection";

interface ToolPageProps {
  params: Promise<{ slug: string }>;
}

/** Single lookup used by metadata + render, so the two can never disagree. */
function findTool(slug: string) {
  for (const category of categories) {
    const tool = category.tools.find((t) => t.slug === slug);
    if (tool) return { category, tool };
  }
  return null;
}

// Pre-render EVERY calculator page at build time — one static HTML file per
// tool, ideal for SEO and instant loads.
export function generateStaticParams() {
  return categories.flatMap((category) =>
    category.tools.map((tool) => ({
      slug: tool.slug,
    })),
  );
}

// Dynamic title / description / OpenGraph, derived from the same data the
// page renders. Falls back gracefully for unknown combos.
export async function generateMetadata({ params }: ToolPageProps): Promise<Metadata> {
  const { slug } = await params;
  const found = findTool(slug);
  if (!found) {
    return { title: "Calculator not found" };
  }

  const { tool } = found;
  const content = getCalculatorContent(tool.slug, tool.name);
  const title = `${tool.name} – Free & Instant | CalcHub`;

  return {
    title,
    description: content.intro[0],
    openGraph: {
      title,
      description: content.intro[0],
      type: "website",
    },
  };
}

export default async function ToolPage({ params }: ToolPageProps) {
  const { slug } = await params;
  const found = findTool(slug);
  if (!found) notFound(); // renders src/app/not-found.tsx

  const { category, tool } = found;
  const content = getCalculatorContent(tool.slug, tool.name);
  const CalculatorComponent = calculatorRegistry[tool.slug];
  const related = category.tools.filter((t) => t.slug !== tool.slug);

  return (
    <div className="mx-auto max-w-4xl px-4 py-12 sm:px-6">
      <Breadcrumbs
        items={[
          { label: "Home", href: "/" },
          { label: category.name, href: `/tools?category=${category.slug}` },
          { label: tool.name },
        ]}
      />

      {/* H1 + intro */}
      <h1 className="mt-6 text-3xl font-bold tracking-tight text-slate-900 sm:text-4xl">
        {tool.name}
      </h1>
      <div className="mt-4 space-y-4 text-lg leading-relaxed text-slate-600">
        {content.intro.map((paragraph) => (
          <p key={paragraph.slice(0, 32)}>{paragraph}</p>
        ))}
      </div>

      {/* The interactive calculator (client island) — or Coming Soon */}
      <div className="mt-10 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8">
        {CalculatorComponent ? (
          <CalculatorComponent />
        ) : (
          <div className="flex flex-col items-center py-10 text-center">
            <span className="grid h-14 w-14 place-items-center rounded-full bg-slate-100">
              <CalendarClock className="h-7 w-7 text-slate-400" />
            </span>
            <h2 className="mt-4 text-lg font-semibold text-slate-900">
              Coming soon
            </h2>
            <p className="mt-1 max-w-sm text-sm text-slate-600">
              The {tool.name} is on the roadmap. In the meantime, explore the
              related calculators below.
            </p>
          </div>
        )}
      </div>

      {/* How to use */}
      <section className="mt-12">
        <h2 className="text-2xl font-bold text-slate-900">
          How to Use This Calculator
        </h2>
        <ol className="mt-5 space-y-4">
          {content.howToUse.map((step, index) => (
            <li key={step} className="flex gap-4">
              <span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-indigo-50 text-sm font-semibold text-indigo-600">
                {index + 1}
              </span>
              <span className="pt-0.5 leading-relaxed text-slate-600">
                {step}
              </span>
            </li>
          ))}
        </ol>
      </section>

      {/* Formula & explanation */}
      <section className="mt-12">
        <h2 className="text-2xl font-bold text-slate-900">
          Formula &amp; Explanation
        </h2>
        <div className="mt-4 rounded-xl border border-slate-200 bg-slate-50 p-5">
          <h3 className="font-semibold text-slate-900">
            {content.formula.title}
          </h3>
          <p className="mt-2 leading-relaxed text-slate-600">
            {content.formula.explanation}
          </p>
        </div>
      </section>

      {/* FAQ (details/summary + FAQPage JSON-LD) */}
      <FaqSection faqs={content.faqs} />

      {/* Related calculators from the same category */}
      {related.length > 0 && (
        <section className="mt-12">
          <h2 className="text-2xl font-bold text-slate-900">
            Related Calculators
          </h2>
          <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {related.map((t) => (
              <CalculatorCard
                key={t.slug}
                title={t.name}
                description={t.description}
                icon={t.icon}
                href={`/tools/${category.slug}/${t.slug}`}
              />
            ))}
          </div>
        </section>
      )}
    </div>
  );
}
